    const hint = isLast ? 'TAP → RESULTS' : `TAP → NEXT  (${this.revealItemIndex + 1}/${this.revealItems.length})`;
    const tapHint = this.add.text(200, 576, hint, {
      fontSize: '13px', color: '#555555', fontFamily: 'monospace',
