      }

      // WP 배지 (우상단)
      const wpBadge = this.add.text(x + cardW / 2, y - cardH / 2 + 2, 'WP', {
        fontSize: '8px', color: WP_ACCENT_HEX, backgroundColor: '#000000cc',
